'use strict';
let editingRecipe=null,pendingPlanDay=null,selectedMenuDay=today(),menuMonth=today().slice(0,7),editingPlan=null;

const weekPicker=document.querySelector('.week-picker');
weekPicker.hidden=true;
const menuCalendar=document.createElement('section');
menuCalendar.className='menu-calendar';
menuCalendar.setAttribute('aria-label','Календарь меню');
weekPicker.after(menuCalendar);

const restockTab=document.createElement('button');
restockTab.dataset.tab='restock';restockTab.setAttribute('aria-pressed','false');
restockTab.innerHTML='Пора пополнить <span id="restock-count"></span>';
document.querySelector('.tabs').append(restockTab);
const shoppingPanel=document.querySelector('[data-panel="shopping"]'),restockPanel=document.createElement('section');
restockPanel.dataset.panel='restock';restockPanel.hidden=true;
restockPanel.innerHTML='<div class="section-heading"><div><h2>Пора пополнить</h2><p class="caption">Покупки из запасов и выбранного меню</p></div></div>';
for(const selector of ['#menu-shopping-title','#menu-shopping','.connection-card','#shopping']){const node=shoppingPanel.querySelector(selector);if(node)restockPanel.append(node)}
shoppingPanel.after(restockPanel);restockTab.onclick=()=>tab('restock');
if(!ready)restockPanel.insertAdjacentHTML('afterbegin',HubSkeleton.html('food-restock'));
shoppingPanel.querySelector('.section-heading')?.remove();

const planAction=document.createElement('dialog');
planAction.id='plan-action';planAction.innerHTML='<form id="plan-action-form"><div class="dialog-head"><h2 id="plan-action-title">Дни блюда</h2><button type="button" data-close-plan-action aria-label="Закрыть">✕</button></div><fieldset><legend>Что сделать?</legend><div class="plan-action-modes"><label><input type="radio" name="mode" value="copy" checked>Повторить по дням</label><label><input type="radio" name="mode" value="move">Перенести</label></div></fieldset><div id="plan-copy-fields"><div class="plan-weekdays"></div><button type="button" class="secondary" id="plan-workdays">Пн–Пт</button></div><label id="plan-move-field" hidden>Новая дата<input name="target" type="date" min="2000-01-01" max="2100-12-31"></label><p id="plan-action-error" role="alert"></p><button class="primary full" type="submit">Сохранить</button></form>';
document.body.append(planAction);

function foodExtras(next){next.recipes??=[];next.plans??=[];return next}
function ingredientRow(item={name:'',quantity:'',unit:'г'}){return `<div class="ingredient-row"><label>Продукт<input data-ingredient="name" maxlength="80" required value="${esc(item.name)}" placeholder="Рис"></label><label>Количество<input data-ingredient="quantity" type="number" min="0.01" max="1000000" step="any" required value="${esc(item.quantity)}"></label><label>Единица<select data-ingredient="unit">${['г','мл','шт'].map(u=>`<option ${u===item.unit?'selected':''}>${u}</option>`).join('')}</select></label><button type="button" data-remove-ingredient aria-label="Убрать ингредиент">×</button></div>`}

function renderMenuCalendar(){
 const [year,month]=menuMonth.split('-').map(Number),first=new Date(year,month-1,1),offset=(first.getDay()+6)%7,last=new Date(year,month,0).getDate(),previous=new Date(year,month-1,0).getDate();
 const cells=Array.from({length:42},(_,index)=>{let number=index-offset+1,cellMonth=month,cellYear=year;if(number<1){number=previous+number;cellMonth--;if(cellMonth<1){cellMonth=12;cellYear--}}else if(number>last){number-=last;cellMonth++;if(cellMonth>12){cellMonth=1;cellYear++}}const value=`${cellYear}-${String(cellMonth).padStart(2,'0')}-${String(number).padStart(2,'0')}`;return `<button type="button" data-menu-day="${value}" class="${value.slice(0,7)!==menuMonth?'outside ':''}${value===selectedMenuDay?'selected':''}" aria-pressed="${value===selectedMenuDay}">${number}</button>`}).join('');
 menuCalendar.innerHTML=`<header><button type="button" data-menu-month="-1" aria-label="Предыдущий месяц">←</button><strong>${first.toLocaleDateString('ru',{month:'long',year:'numeric'})}</strong><button type="button" data-menu-month="1" aria-label="Следующий месяц">→</button></header><div class="calendar-weekdays" aria-hidden="true">${['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map(x=>`<span>${x}</span>`).join('')}</div><div class="calendar-days">${cells}</div>`;
}
function changeMenuMonth(offset){const [year,month]=menuMonth.split('-').map(Number),next=new Date(year,month-1+offset,1);menuMonth=`${next.getFullYear()}-${String(next.getMonth()+1).padStart(2,'0')}`;renderMenuCalendar()}
function chooseMenuDay(day){selectedMenuDay=day;menuMonth=day.slice(0,7);$('#week-date').value=FoodPlan.monday(day);renderPlanner()}
menuCalendar.onclick=event=>{const button=event.target.closest('button');if(button?.dataset.menuDay)chooseMenuDay(button.dataset.menuDay);if(button?.dataset.menuMonth)changeMenuMonth(Number(button.dataset.menuMonth))};

function renderPlanner(){
 foodExtras(state);
 const first=FoodPlan.useFirst(pantryLots(),today()),expired=pantryLots().filter(s=>s.quantity>0&&s.expiry&&s.expiry<today());
 $('#use-first').innerHTML=(expired.length?`<div class="expiry-warning"><h3>Срок годности прошёл</h3><p>${expired.map(s=>esc(s.name)).join(', ')}. Эти запасы не учитываются в покупках для меню.</p></div>`:'')+(first.length?`<div class="use-first"><p class="eyebrow">Использовать первым</p>${first.map(s=>`<div><strong>${esc(s.name)}</strong><span>${s.expiry===today()?'Годен до сегодня':`До ${dateText(s.expiry)}`} · ${number(s.quantity)} ${esc(s.unit)}</span></div>`).join('')}</div>`:'');
 const recipes=state.recipes;
 $('#favorites').innerHTML=recipes.length?recipes.map(r=>`<article class="favorite-row"><div><h3>${esc(r.name)}</h3><p>${esc(r.kind)}${r.ingredients.length?` · ${r.ingredients.length} ${plural(r.ingredients.length,['ингредиент','ингредиента','ингредиентов'])}`:''}</p></div><div class="favorite-actions">${r.ingredients.length?`<button data-cook-recipe="${esc(r.id)}">Приготовил</button>`:''}<button data-repeat-recipe="${esc(r.id)}">Записать</button><button data-edit-recipe="${esc(r.id)}" aria-label="Изменить блюдо ${esc(r.name)}">✎</button></div></article>`).join(''):'<p class="caption">Сохрани любимый завтрак: в следующий раз хватит одного нажатия.</p>';
 const start=FoodPlan.monday($('#week-date').value||selectedMenuDay);$('#week-date').value=start;
 if(selectedMenuDay<start||selectedMenuDay>plusDays(start,6))selectedMenuDay=start;
 $('#week-label').textContent=`${dateText(start)} — ${dateText(plusDays(start,6))}`;
 renderMenuCalendar();
 const strip=Array.from({length:7},(_,i)=>{const day=plusDays(start,i);return `<button type="button" data-menu-week-day="${day}" class="${day===selectedMenuDay?'active':''}" aria-pressed="${day===selectedMenuDay}"><span>${dateValue(day).toLocaleDateString('ru',{weekday:'short'})}</span><strong>${dateValue(day).getDate()}</strong></button>`}).join('');
 const plans=state.plans.filter(plan=>plan.date===selectedMenuDay);
 const entries=plans.length?plans.map(plan=>{const recipe=recipes.find(r=>r.id===plan.recipeId);return `<div class="menu-entry"><div><strong>${esc(recipe?.name||'Блюдо удалено')}</strong><p>${esc(recipe?.kind||'')} · ${number(plan.servings)} ${plural(plan.servings,['порция','порции','порций'])}</p></div><button class="secondary" data-plan-action="${esc(plan.id)}">Дни</button><button data-remove-plan="${esc(plan.id)}" aria-label="Убрать из меню ${esc(recipe?.name||'блюдо')}">×</button></div>`}).join(''):'<p class="caption">На этот день пока ничего не запланировано.</p>';
 $('#week-menu').innerHTML=`<div class="menu-week-strip">${strip}</div><section class="menu-day"><header><h3>${dateValue(selectedMenuDay).toLocaleDateString('ru',{weekday:'long',day:'numeric',month:'long'})}</h3><button data-plan-day="${selectedMenuDay}" aria-label="Добавить блюдо на ${dateText(selectedMenuDay)}">＋</button></header>${entries}</section>`;
 const rows=FoodPlan.shopping(state.plans,recipes,pantryLots(),start,today()),missing=rows.filter(r=>r.missing>0);
 $('#menu-shopping-title').textContent=`Для меню · ${dateText(start)} — ${dateText(plusDays(start,6))}`;
 $('#menu-shopping').innerHTML=rows.length?`<p class="caption">Текущий запас вычтен один раз. Учитываются сегодня и будущие дни выбранной недели; продукты, чей срок истечёт к дате блюда, исключены.</p>${missing.length?missing.map(r=>`<article class="buy-ingredient"><div><h3>${esc(r.name)}</h3><p>Нужно ${number(r.needed)} ${esc(r.unit)} · есть ${number(r.available)} ${esc(r.unit)}</p></div><strong>${number(r.missing)} ${esc(r.unit)}</strong><button data-add-shopping="${esc(r.name)}">В список</button></article>`).join(''):'<div class="empty"><h3>Всё для меню уже есть</h3><p>По записанным ингредиентам и текущему остатку.</p></div>'}`:'<p class="caption">Добавь блюда с ингредиентами в меню — здесь появится, чего не хватает.</p>';
 const incomplete=state.plans.filter(p=>p.date>=start&&p.date<=plusDays(start,6)&&p.date>=today()).some(p=>!recipes.find(r=>r.id===p.recipeId)?.ingredients.length);
 if(incomplete)$('#menu-shopping').insertAdjacentHTML('beforeend','<p class="expiry">У некоторых блюд нет ингредиентов. Добавь их в любимых блюдах, чтобы список покупок был полным.</p>');
 const auto=shoppingLinks.filter(link=>link.task&&!link.suppressed).length,count=missing.length+auto;$('#restock-count').textContent=count||'';
}

function recipeEditor(id,meal,planDay=null){pendingPlanDay=planDay;editingRecipe=id||null;const r=state.recipes.find(r=>r.id===id)||meal||{},f=$('#recipe-form');f.reset();f.elements.name.value=r.name||'';f.elements.kind.value=r.kind||'Завтрак';f.elements.note.value=r.note||'';f.elements.kcal.value=r.kcal??'';$('#ingredients').innerHTML=(r.ingredients||[]).map(ingredientRow).join('');$('#recipe-error').textContent='';$('#recipe-delete').hidden=!id;$('#recipe-editor').showModal()}
$('#recipe-editor').addEventListener('close',()=>{pendingPlanDay=null});
$('#recipe-add').onclick=()=>recipeEditor();
$('#ingredient-add').onclick=()=>$('#ingredients').insertAdjacentHTML('beforeend',ingredientRow());
$('#ingredients').onclick=e=>{if(e.target.closest('[data-remove-ingredient]'))e.target.closest('.ingredient-row').remove()};
$('#recipe-form').onsubmit=async e=>{e.preventDefault();const v=e.currentTarget.elements,name=v.name.value.trim();if(!name){$('#recipe-error').textContent='Напиши название блюда.';return}const ingredients=[...$('#ingredients').querySelectorAll('.ingredient-row')].map(row=>({name:row.querySelector('[data-ingredient=name]').value.trim(),quantity:Number(row.querySelector('[data-ingredient=quantity]').value),unit:row.querySelector('[data-ingredient=unit]').value}));if(ingredients.some(i=>!i.name||!Number.isFinite(i.quantity)||i.quantity<=0)){ $('#recipe-error').textContent='Укажи продукт и количество для каждого ингредиента.';return}const next=structuredClone(state),r={id:editingRecipe||crypto.randomUUID(),name,kind:v.kind.value,note:v.note.value.trim(),kcal:v.kcal.value===''?null:Number(v.kcal.value),ingredients};if(editingRecipe)next.recipes[next.recipes.findIndex(r=>r.id===editingRecipe)]=r;else next.recipes.push(r);if(await persist(next)){const day=pendingPlanDay;pendingPlanDay=null;$('#recipe-editor').close();toast('Блюдо сохранено в любимых.');if(day)planEditor(day,r.id)}};
$('#recipe-delete').onclick=async()=>{if(state.plans.some(p=>p.recipeId===editingRecipe)){$('#recipe-error').textContent='Сначала убери это блюдо из меню — оно там ещё запланировано.';return}const next=structuredClone(state);next.recipes=next.recipes.filter(r=>r.id!==editingRecipe);if(await persist(next))$('#recipe-editor').close()};
$('#favorites').onclick=async e=>{const b=e.target.closest('button');if(b?.dataset.editRecipe)recipeEditor(b.dataset.editRecipe);if(b?.dataset.repeatRecipe){const r=state.recipes.find(r=>r.id===b.dataset.repeatRecipe),next=structuredClone(state);next.meals.push({id:crypto.randomUUID(),name:r.name,kind:r.kind,note:r.note,kcal:r.kcal,date:$('#diary-date').value||today(),time:new Date().toTimeString().slice(0,5),consumed:null});if(await persist(next))toast('Блюдо записано в выбранный день. Запасы не списаны.')}};
$('#meals').addEventListener('click',e=>{const id=e.target.closest('[data-favorite-meal]')?.dataset.favoriteMeal;if(id)recipeEditor(null,state.meals.find(m=>m.id===id))});

function planEditor(day,recipeId){if(!state.recipes.length){toast('Добавь любимое блюдо — затем продолжим с выбранной датой.');recipeEditor(null,null,day);return}const f=$('#plan-form');f.reset();f.elements.date.value=day;f.elements.recipe.innerHTML=state.recipes.map(r=>`<option value="${esc(r.id)}">${esc(r.name)}</option>`).join('');if(recipeId)f.elements.recipe.value=recipeId;$('#plan-editor').showModal()}
function openPlanAction(id){const plan=state.plans.find(item=>item.id===id),recipe=state.recipes.find(item=>item.id===plan?.recipeId);if(!plan)return;editingPlan=id;$('#plan-action-title').textContent=recipe?.name||'Блюдо';$('#plan-action-error').textContent='';const start=FoodPlan.monday(plan.date);planAction.querySelector('.plan-weekdays').innerHTML=Array.from({length:7},(_,i)=>{const day=plusDays(start,i);return `<label><input type="checkbox" value="${day}" ${day===plan.date?'checked':''}><span>${dateValue(day).toLocaleDateString('ru',{weekday:'short',day:'numeric'})}</span></label>`}).join('');planAction.querySelector('[name=target]').value=plan.date;planAction.querySelector('[name=mode][value=copy]').checked=true;syncPlanAction();planAction.showModal()}
function syncPlanAction(){const move=planAction.querySelector('[name=mode]:checked').value==='move';$('#plan-copy-fields').hidden=move;$('#plan-move-field').hidden=!move;planAction.querySelector('[name=target]').required=move}
planAction.querySelectorAll('[name=mode]').forEach(input=>input.onchange=syncPlanAction);
planAction.querySelector('[data-close-plan-action]').onclick=()=>planAction.close();
$('#plan-workdays').onclick=()=>planAction.querySelectorAll('.plan-weekdays input').forEach((input,index)=>input.checked=index<5);
$('#week-menu').onclick=async event=>{const button=event.target.closest('button');if(button?.dataset.menuWeekDay)chooseMenuDay(button.dataset.menuWeekDay);if(button?.dataset.planDay)planEditor(button.dataset.planDay);if(button?.dataset.planAction)openPlanAction(button.dataset.planAction);if(button?.dataset.removePlan){const next=structuredClone(state);next.plans=next.plans.filter(p=>p.id!==button.dataset.removePlan);await persist(next)}};
$('#plan-action-form').onsubmit=async event=>{event.preventDefault();const original=state.plans.find(item=>item.id===editingPlan);if(!original)return;const next=structuredClone(state),mode=new FormData(event.currentTarget).get('mode');if(mode==='move'){const target=event.currentTarget.elements.target.value;if(!target){$('#plan-action-error').textContent='Выбери новую дату.';return}next.plans.find(item=>item.id===editingPlan).date=target;selectedMenuDay=target}else{const days=[...planAction.querySelectorAll('.plan-weekdays input:checked')].map(input=>input.value);if(!days.length){$('#plan-action-error').textContent='Выбери хотя бы один день.';return}for(const day of days){if(day===original.date||next.plans.some(item=>item.date===day&&item.recipeId===original.recipeId&&item.servings===original.servings))continue;next.plans.push({...original,id:crypto.randomUUID(),date:day})}}if(await persist(next)){planAction.close();$('#week-date').value=FoodPlan.monday(selectedMenuDay);renderPlanner();toast(mode==='move'?'Блюдо перенесено.':'Блюдо повторено по выбранным дням.')}};
$('#plan-form').onsubmit=async e=>{e.preventDefault();const v=e.currentTarget.elements,next=structuredClone(state);next.plans.push({id:crypto.randomUUID(),date:v.date.value,recipeId:v.recipe.value,servings:Number(v.servings.value)});if(await persist(next)){selectedMenuDay=v.date.value;menuMonth=v.date.value.slice(0,7);$('#week-date').value=FoodPlan.monday(v.date.value);renderPlanner();$('#plan-editor').close();toast('Блюдо добавлено в меню.')}};
$('#week-date').value=FoodPlan.monday(today());
document.querySelectorAll('[data-close-extra]').forEach(b=>b.onclick=()=>$('#'+b.dataset.closeExtra).close());
function demoMenu(d){return {recipes:[{id:'demo-omelet',name:'Омлет с помидорами',kind:'Завтрак',note:'Любимый завтрак',kcal:null,ingredients:[{name:'Яйца',quantity:2,unit:'шт'},{name:'Помидоры',quantity:150,unit:'г'}]},{id:'demo-bowl',name:'Мясо с рисом',kind:'Обед',note:'С зеленью',kcal:null,ingredients:[{name:'Мясо',quantity:300,unit:'г'},{name:'Рис',quantity:100,unit:'г'}]}],plans:[{id:'demo-plan-a',date:d,recipeId:'demo-omelet',servings:1},{id:'demo-plan-b',date:d,recipeId:'demo-bowl',servings:2}]}}
if(ready)renderPlanner();
